def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    """
    Optimize the placement of aisles in a classroom to minimize the amount of chatting between students.

    Parameters:
    - M (int): Number of rows in the classroom.
    - N (int): Number of columns in the classroom.
    - K (int): Number of horizontal aisles to add.
    - L (int): Number of vertical aisles to add.
    - D (int): Number of chatting pairs (unused directly, inferred from chatting_pairs length).
    - chatting_pairs (list of tuples): Each tuple contains (Xi, Yi, Pi, Qi) positions of a chatting pair.

    Returns:
    - (str, str): Two space-separated strings representing the optimal row indices for horizontal aisles
      and column indices for vertical aisles. Empty string if no aisles of that type are chosen.
    """
    import itertools

    # Helper to compute aisles that separate a pair
    def horizontal_aisles_for_pair(r1, r2):
        if r1 == r2:
            return set()
        lo, hi = sorted((r1, r2))
        return set(range(lo, hi))  # aisles between lo and hi-1

    def vertical_aisles_for_pair(c1, c2):
        if c1 == c2:
            return set()
        lo, hi = sorted((c1, c2))
        return set(range(lo, hi))  # aisles between lo and hi-1

    # Precompute aisles for each pair
    pair_h_aisles = []
    pair_v_aisles = []
    for (x, y, p, q) in chatting_pairs:
        pair_h_aisles.append(horizontal_aisles_for_pair(x, p))
        pair_v_aisles.append(vertical_aisles_for_pair(y, q))

    # All possible aisle indices
    all_h_aisles = list(range(1, M))  # 1..M-1
    all_v_aisles = list(range(1, N))  # 1..N-1

    # If the search space is too large, fall back to greedy
    max_combinations = 10**6
    comb_h = itertools.combinations(all_h_aisles, K) if K <= len(all_h_aisles) else []
    comb_v = itertools.combinations(all_v_aisles, L) if L <= len(all_v_aisles) else []

    # Count total combinations
    total_combinations = 0
    try:
        total_combinations = len(list(itertools.combinations(all_h_aisles, K))) * len(list(itertools.combinations(all_v_aisles, L)))
    except Exception:
        total_combinations = max_combinations + 1

    best_h = ()
    best_v = ()
    best_count = -1

    if total_combinations <= max_combinations:
        # Exhaustive search
        for h_sel in comb_h:
            h_set = set(h_sel)
            for v_sel in comb_v:
                v_set = set(v_sel)
                count = 0
                for idx in range(len(chatting_pairs)):
                    if h_set & pair_h_aisles[idx] or v_set & pair_v_aisles[idx]:
                        count += 1
                if count > best_count:
                    best_count = count
                    best_h = h_sel
                    best_v = v_sel
    else:
        # Greedy selection
        # Compute initial benefit for each aisle
        h_benefit = {h: 0 for h in all_h_aisles}
        v_benefit = {v: 0 for v in all_v_aisles}
        for idx in range(len(chatting_pairs)):
            for h in pair_h_aisles[idx]:
                h_benefit[h] += 1
            for v in pair_v_aisles[idx]:
                v_benefit[v] += 1

        selected_h = set()
        selected_v = set()
        covered = [False] * len(chatting_pairs)

        for _ in range(K):
            # Choose horizontal aisle with max marginal benefit
            best_h_aisle = None
            best_h_gain = -1
            for h in all_h_aisles:
                if h in selected_h:
                    continue
                gain = 0
                for idx in range(len(chatting_pairs)):
                    if not covered[idx] and h in pair_h_aisles[idx]:
                        gain += 1
                if gain > best_h_gain:
                    best_h_gain = gain
                    best_h_aisle = h
            if best_h_aisle is not None:
                selected_h.add(best_h_aisle)
                for idx in range(len(chatting_pairs)):
                    if not covered[idx] and best_h_aisle in pair_h_aisles[idx]:
                        covered[idx] = True

        for _ in range(L):
            best_v_aisle = None
            best_v_gain = -1
            for v in all_v_aisles:
                if v in selected_v:
                    continue
                gain = 0
                for idx in range(len(chatting_pairs)):
                    if not covered[idx] and v in pair_v_aisles[idx]:
                        gain += 1
                if gain > best_v_gain:
                    best_v_gain = gain
                    best_v_aisle = v
            if best_v_aisle is not None:
                selected_v.add(best_v_aisle)
                for idx in range(len(chatting_pairs)):
                    if not covered[idx] and best_v_aisle in pair_v_aisles[idx]:
                        covered[idx] = True

        best_h = tuple(sorted(selected_h))
        best_v = tuple(sorted(selected_v))

    # Prepare output strings
    h_str = ' '.join(str(i) for i in sorted(best_h))
    v_str = ' '.join(str(i) for i in sorted(best_v))
    return h_str, v_str

