def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        # Determine sign
        if not terms:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '+' if coeff > 0 else '-'
        abs_coeff = abs(coeff)
        # Coefficient string
        if degree == 0:
            coeff_str = str(abs_coeff)
        else:
            coeff_str = '' if abs_coeff == 1 else str(abs_coeff)
        # Variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''
        terms.append(f"{sign}{coeff_str}{var_str}")
    return ''.join(terms) if terms else '0'

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    Parameters:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Basic validation: encoded and original must be same length
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    reverse_mapping = {}

    for e_char, o_char in zip(encoded, original):
        # Ensure characters are uppercase letters
        if not ('A' <= e_char <= 'Z') or not ('A' <= o_char <= 'Z'):
            return "Failed"
        # Check consistency of mapping
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"
        else:
            mapping[e_char] = o_char
        # Ensure one-to-one mapping
        if o_char in reverse_mapping:
            if reverse_mapping[o_char] != e_char:
                return "Failed"
        else:
            reverse_mapping[o_char] = e_char

    # Mapping must cover all 26 letters
    if len(mapping) != 26 or len(reverse_mapping) != 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def string_transformation(A: str, B: str, rules: list):
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps. Returns the minimum number of steps if possible,
    otherwise returns "NO ANSWER!".
    """
    if A == B:
        return 0

    max_steps = 10
    queue = [(A, 0)]
    visited = {A}

    while queue:
        current, steps = queue.pop(0)
        if steps >= max_steps:
            continue

        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1  # allow overlapping matches

    return "NO ANSWER!"

